from pwn import *
import binascii

def print_hex_blocks(data):
    blocks = [data[i:i+16] for i in range(0, len(data), 16)]
    for i, block in enumerate(blocks):
        print(f'Block {i}: {binascii.hexlify(block).decode()}')

def get_cookie(conn):
    conn.sendline(b'aaaaaaaaaaaaaaaa')
    try:
        response = conn.recvuntil(b'Enter your username', timeout=2).decode()
        for line in response.split('\n'):
            if 'Cookie is:' in line:
                return line.split('Cookie is: ')[1].strip()
    except Exception as e:
        print(f"Error receiving response: {e}")
    return None

def try_cookie(conn, cookie):
    conn.sendline(cookie.encode())
    try:
        return conn.recvuntil(b'Enter your username', timeout=2).decode()
    except:
        return ""

# Try to flip bits to change "user" to "admin"
def bit_flip_admin(original_cookie):
    blocks = [original_cookie[i:i+16] for i in range(0, len(original_cookie), 16)]

    # Known target change: user -> admin
    # Try common positions where "user" might be stored
    positions_to_try = [
        # First byte positions that could contain 'user'
        (0, 0), (0, 1), (0, 2), (0, 3), (0, 4),
        # Try to flip 'u' (0x75) to 'a' (0x61)
        (0, 5), (1, 5), (2, 5), (3, 5),
        # Try some key byte positions
        (0, 0x75), (1, 0x75), (2, 0x75), (3, 0x75)
    ]

    results = []
    for block_idx, byte_pos in positions_to_try:
        if block_idx >= len(blocks):
            continue

        modified_block = bytearray(blocks[block_idx])
        # Flip each bit in the byte
        for bit in range(8):
            modified_block[byte_pos] ^= (1 << bit)
            modified_cookie = bytes(modified_block)
            for i, b in enumerate(blocks):
                if i != block_idx:
                    modified_cookie += b
            results.append(binascii.hexlify(modified_cookie).decode())
            # Reset for next bit
            modified_block[byte_pos] ^= (1 << bit)

    return results

# Connect to the server
conn = remote('crypto.chal.csaw.io', 8000)

try:
    # Wait for initial prompt
    initial = conn.recvuntil(b'Enter your username (no whitespace): ')
    print("Initial prompt received")

    # Get original cookie
    cookie = get_cookie(conn)
    if not cookie:
        print("Failed to get cookie")
        exit(1)

    print(f"[+] Got cookie: {cookie}")
    original_cookie = binascii.unhexlify(cookie)
    print_hex_blocks(original_cookie)

    # Try cookie modifications targeting admin access
    print("\n[*] Trying targeted modifications...")
    modified_cookies = bit_flip_admin(original_cookie)

    for modified_cookie in modified_cookies:
        print(f"\n[*] Trying modified cookie: {modified_cookie}")
        response = try_cookie(conn, modified_cookie)

        if 'flag{' in response:
            print('\n[!] FLAG FOUND!')
            print(response)
            break
        elif 'admin' in response.lower():
            print('\n[!] Admin access detected!')
            print(response)

except Exception as e:
    print(f"Error occurred: {str(e)}")
finally:
