from pwn import *
import binascii

def split_blocks(cookie):
    return [cookie[i:i+16] for i in range(0, len(cookie), 16)]

def test_username(username):
    try:
        r = remote("crypto.chal.csaw.io", 8000, timeout=5)
        r.recvuntil(b"Enter username: ")
        r.sendline(username.encode())
        resp = r.recvuntil(b"Enter username: ", timeout=5, drop=True)
        r.close()

        if b"Here's your cookie:" in resp:
            cookie = resp.split(b"Here's your cookie: ")[1].split(b"\n")[0]
            try:
                cookie_bytes = binascii.unhexlify(cookie)
                blocks = split_blocks(cookie_bytes)
                return {
                    'raw': cookie_bytes,
                    'hex': cookie.decode(),
                    'blocks': [binascii.hexlify(b).decode() for b in blocks]
                }
            except:
                return None
    except Exception as e:
        print(f"Error with {username}: {str(e)}")
    return None

